import {model,NODES,WORLDS,INTERESTS,novaLine} from './constellation.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function novaAvatar(state,world=3,size='medium',m=model(state)){
 const hue=Math.round(m.glow*100),glow=12+m.glow*35;
 return `<span class="nova-avatar ${size} costume-${world}" style="--nova-hue:${hue}deg;--nova-glow:${glow}px" role="img" aria-label="Nova, your AI learning spark, ${m.earned} remembered discoveries"><img src="nova.png" alt=""/><span class="nova-costume" aria-hidden="true">${['✿','❧','⋈','✧'][world]}</span><i class="orbit orbit-one"></i><i class="orbit orbit-two"></i></span>`;
}
export function novaSpeech(state,world,line,kind='normal',m=model(state)){return `<section class="nova-speech ${kind}">${novaAvatar(state,world,'small',m)}<div><span class="nova-signature">NOVA <small>AI learning spark</small></span><p>${esc(line)}</p></div><button class="nova-info" data-action="nova" aria-label="About Nova">i</button></section>`;}
export function worldTabs(world){return `<nav class="world-tabs" aria-label="Choose your world">${WORLDS.map((w,i)=>`<button data-world="${i}" aria-pressed="${i===world}" class="${i===world?'selected':''}"><span aria-hidden="true">${['✿','❧','◒','✧'][i]}</span><span>${w.name}</span></button>`).join('')}</nav>`;}
export function nodeCard(n){return `<button class="discovery-card stage-${n.stage.split(' ')[0].toLowerCase()}" data-node="${n.id}"><span class="discovery-icon">${n.unlocked?n.order:'🔒'}</span><span><strong>${n.name}</strong><small>${n.stage}</small></span><span class="node-stars" aria-label="${n.peak} of 3 evidence milestones">${'✦'.repeat(n.peak)}${'·'.repeat(3-n.peak)}</span></button>`;}
export function homeView(state,world,week){
 const m=model(state),w=m.worlds[world],r=m.recommendation;const coords=[[17,57],[31,42],[45,61],[59,43],[73,62],[84,31]];
 return `<section class="greeting"><div><span class="nova-kicker">YOUR GROWING UNIVERSE</span><h1>A little wonder, ${esc(state.name)}.</h1><p>Four worlds. One bright trail of discoveries.</p></div><button class="text-button" data-action="interests">${INTERESTS.filter(x=>state.nova?.interests.includes(x.id)).map(x=>x.icon).join(' ')} My interests</button></section>${worldTabs(world)}<div class="nova-dashboard"><div><section class="nova-world world-${world}" style="--world-accent:${w.color}" aria-label="${w.name} adventure map"><img class="nova-landscape" src="worlds/${w.asset}" alt="${w.name}: ${w.desc}"/><div class="world-shade"></div><div class="nova-world-title"><span class="eyebrow">${w.tag}</span><h2>${w.name}</h2><p>${w.desc}</p></div>${w.unlocked?`<div class="earned-landscape earned-${world} tier-${w.unlocked}" aria-hidden="true"><span>✧</span><span>✦</span><span>✧</span>${w.unlocked>1?'<i></i>':''}${w.unlocked>2?'<b>✺</b>':''}</div>`:''}${w.nodes.map((n,i)=>`<button class="map-discovery ${n.peak?'lit':''} ${!n.unlocked?'is-locked':''} ${r.id===n.id?'recommended':''}" style="left:${coords[i][0]}%;top:${coords[i][1]}%" data-node="${n.id}" aria-label="Level ${n.order}, ${n.name}: ${n.stage}"><span>${n.unlocked?n.order:'🔒'}</span><small>${n.name}</small></button>`).join('')}<div class="map-caption"><span>${w.nodes.filter(n=>n.peak).length} / 6 discoveries taking root</span><button data-nav="skills">See constellation ↗</button></div></section><section class="nova-quest"><span class="quest-badge">${r.due?'↺':'✦'}</span><div><span class="nova-kicker">${r.due?'A TINY RETURN TRIP':r.fragile?'A HELPFUL LITTLE DETOUR':'NOVA’S NEXT DISCOVERY'} · ${WORLDS[r.world].name}</span><h2>${r.name}</h2><p>${m.reason}</p></div><button class="primary" data-discover="${r.id}">${r.due?'Rekindle it':'Let’s explore'} →</button></section>${novaSpeech(state,world,novaLine('welcome',{index:state.sessions.length}), 'normal',m)}<div class="section-title"><h2>What’s growing here</h2><button class="text-button" data-action="world-story">Our journey ↗</button></div><div class="landmark-row">${w.landmarks.map((name,i)=>`<button class="landmark ${i<w.unlocked?'earned':''}" data-landmark="${i}" aria-label="${name}, ${i<w.unlocked?'discovered':'grows with learning'}"><span>${i<w.unlocked?['✧','❖','✺'][i]:'◇'}</span><strong>${name}</strong><small>${i<w.unlocked?'Discovered · yours to keep':`${[1,6,12][i]} learning milestones`}</small></button>`).join('')}</div></div><aside class="nova-rail"><section class="glow-card">${novaAvatar(state,world,'large',m)}<span class="nova-kicker">YOUR IDEAS, MADE VISIBLE</span><h3>A growing glow.</h3><p>${m.rooted} discoveries taking root.<br>${m.earned} remembered across days.</p><button class="text-button" data-nav="skills">Follow the connections →</button><small>My color grows with your learning. Taking a break never takes it away.</small></section><section class="panel"><div class="panel-head"><h3>A little, often</h3><span class="tag">${state.days.length} days explored</span></div>${week}<p class="habit-note">Your discoveries will be here whenever you return.</p></section><section class="ready-card"><span class="nova-kicker">NEW PATHS OPENING</span><h3>Ready for a little discovery?</h3>${m.fringe.slice(0,3).map(n=>`<button data-discover="${n.id}"><span>${n.icon}</span>${n.name} <b>→</b></button>`).join('')||'<p>Let’s revisit an idea and see what connects.</p>'}</section></aside></div>`;
}
export function constellationView(state){const m=model(state);const pos=Object.fromEntries(NODES.map((n,i)=>[n.id,{x:117+n.world*238,y:93+(i%6)*91}]));
 return `<section class="greeting"><div><span class="nova-kicker">EVERY IDEA CONNECTS</span><h1>Your constellation.</h1><p>Tap a star to see what it connects to. Complete each level to open the next one.</p></div></section><div class="constellation-key"><span>🔒 Complete earlier levels</span><span>◉ Ready to explore</span><span>✦ Taking root</span><span>✦✦✦ Remembered</span></div><div class="constellation-scroll" tabindex="0" aria-label="Skill constellation. Scroll sideways on smaller screens."><div class="constellation-board">${WORLDS.map((w,i)=>`<div class="constellation-column" style="left:${i*238}px;--column-color:${w.color}"><h2>${w.name}</h2></div>`).join('')}<svg class="constellation-lines" viewBox="0 0 950 630" aria-hidden="true">${NODES.flatMap(n=>n.prereqs.map(p=>`<path class="${m.nodes[p].solid?'connected':''}" d="M ${pos[p].x} ${pos[p].y} C ${pos[p].x+70} ${pos[p].y+30},${pos[n.id].x-70} ${pos[n.id].y-30},${pos[n.id].x} ${pos[n.id].y}"/>`)).join('')}</svg>${NODES.map(n=>{const s=m.nodes[n.id];return `<button class="constellation-node ${s.peak?'lit':''} ${!s.unlocked?'is-locked':''} ${s.ready?'ready':''} ${s.due||s.fragile?'rekindle':''}" style="left:${pos[n.id].x}px;top:${pos[n.id].y}px;--node-color:${WORLDS[n.world].color}" data-node="${n.id}" aria-label="Level ${s.order}, ${n.name}, ${s.stage}, ${s.checks} recall checks"><span>${!s.unlocked?'🔒':s.peak?'✦':s.order}</span><strong>${n.name}</strong><small>${s.stage}</small></button>`}).join('')}</div></div><p class="constellation-caption">Lines show ideas that help one another. A refresher changes the next step, never what you’ve already earned.</p>${novaSpeech(state,m.recommendation.world,m.reason)}<div class="section-title"><h2>Your level journey</h2><span class="small muted">24 connected ideas</span></div><div class="world-discovery-lists">${m.worlds.map(w=>`<section><h3>${w.name}</h3>${w.nodes.map(nodeCard).join('')}</section>`).join('')}</div>`;
}
export function evidenceView(state){const m=model(state);return `<section class="greeting"><div><span class="nova-kicker">THE LEARNING BEHIND THE LIGHT</span><h1>Every connection has evidence.</h1><p>${esc(state.name)}’s learning journal · Saved to your account</p></div><button class="secondary" data-action="settings">Settings</button></section><div class="metric-row"><div class="metric"><div class="number">${m.rooted}</div><p>Ideas taking root</p></div><div class="metric"><div class="number">${Object.values(m.nodes).filter(n=>n.mastered).length}</div><p>Remembered now</p></div><div class="metric"><div class="number">${m.fringe.length}</div><p>Ready-to-learn ideas</p></div><div class="metric"><div class="number">${state.attempts.filter(a=>a.node).length}</div><p>Observed first attempts</p></div></div><div class="wide-panel"><h2>Why this next step?</h2><p><strong>${m.recommendation.name}:</strong> ${m.reason}</p><p class="small muted">The same model chooses practice, review, challenge size, and world suggestions. Levels open in order when the previous idea takes root. Linked skills guide practice and review; success in one never automatically certifies another.</p></div><div class="wide-panel journal-evidence"><div class="table-scroll"><table class="evidence"><thead><tr><th>Discovery</th><th>First-attempt evidence</th><th>Recall checks</th><th>Current stage</th><th>Estimated review</th></tr></thead><tbody>${Object.values(m.nodes).map(n=>`<tr><td>${n.name}</td><td>${n.history.length?Math.round(n.accuracy*100)+'% · latest '+Math.min(8,n.history.length):'No direct evidence'}</td><td>${n.checks}</td><td>${n.stage}</td><td>${n.fragile||n.due?'Useful now':n.solid&&n.reviewAt?new Date(n.reviewAt).toLocaleDateString():'After fluent practice'}</td></tr>`).join('')}</tbody></table></div></div><div class="info"><strong>How to read this</strong><p>Taking root requires 7 of the last 8 answers correct without help, at least two question formats, a challenge at level 2 or higher, and 6 comfortable responses (45 seconds in K–1, 30 seconds later). Comfortable pace removes the speed requirement. “Remembered” additionally needs three successful recall checks on separate days and current evidence that remains strong.</p><p>Recall windows adapt to each skill’s history. The forgetting estimate is a heuristic, not a measured probability or a diagnosis. This is a prerequisite-graph prototype, not an ALEKS implementation or a validated Knowledge Space Theory assessment. Learning gains still need an independent study.</p><p>Nova uses the adaptive model and reviewed phrases; there is no generative chat or personal-message collection. Selected interests are saved and can be changed or cleared. For personal concerns, Nova points the child toward a trusted grown-up.</p>${state.attempts.some(a=>!a.node)?'<p>Earlier practice remains in your export. It does not automatically certify the new, more specific discoveries.</p>':''}</div><div class="parent-actions"><button class="secondary" data-action="export">Download learning journal</button><button class="secondary" data-action="account">My account</button><button class="text-button" data-action="reset">Reset learning progress</button></div>`;}
